 async mcp(r:Request,auth:{id:string,works:string[]|null}){if(r.method==='GET')return new Response(null,{status:405,headers:{Allow:'POST'}});if(r.method==='DELETE')return new Response(null,{status:204});const b:any=await r.json();if(b.method?.startsWith('notifications/'))return new Response(null,{status:202});let result;try{switch(b.method){case'initialize':result={protocolVersion:'2025-03-26',capabilities:{tools:{listChanged:false}},serverInfo:{name:'note4-platform',version:'1.1.0'}};break;case'ping':result={};break;case'tools/list':{const token=r.headers.get('Authorization')?.replace(/^Bearer /,'');const grant=JSON.parse(this.env.MCP_GRANTS||'{}')[token??''];result={tools:this.toolDefs().filter(t=>(!grant?.tools||grant.tools.includes(t.name))&&(!auth.works||t.name!=='create_work'))};break;}case'tools/call':try{const token=r.headers.get('Authorization')?.replace(/^Bearer /,'');const grant=JSON.parse(this.env.MCP_GRANTS||'{}')[token??''];if(grant?.tools&&!grant.tools.includes(b.params.name))fail('Tool permission denied',403);result={content:[{type:'text',text:JSON.stringify(await this.callTool(b.params.name,b.params.arguments??{},auth))}]};}catch(e:any){result={isError:true,content:[{type:'text',text:e.message}]};}break;default:return json({jsonrpc:'2.0',id:b.id,error:{code:-32601,message:'Method not found'}});}return json({jsonrpc:'2.0',id:b.id,result});}catch(e:any){return json({jsonrpc:'2.0',id:b.id,error:{code:-32602,message:e.message}});}}
